#!/usr/bin/env bash
# ═══════════════════════════════════════════════════════════════════════════
# release-contract.sh — «أخضر» لا يعني «قابلٌ للرفع» (v15.81)
# ───────────────────────────────────────────────────────────────────────────
# 🔴 العيبُ المقيس الذي وُضع هذا العقدُ لأجله: سبعُ جلساتٍ لسير آيفون،
#    خطوتا التوقيع **skipped ١٤/١٤ مرّة** (الأسرارُ غائبة)، وجلستان من ٧
#    نوفمبر ٢٠٢٦ خضراوان تماماً بـ`artifacts total=0`. و`skipped` **لا
#    يُلوّن السيرَ أحمر**، فمن يقرأ لوحةَ Actions يرى بناءين خضراوين
#    ويستنتج أن التطبيقين جاهزان — وهما لم يُنتجا بايتاً واحداً قابلاً
#    للتثبيت. أندرويد نفسُ الشكل: `bundleRelease` يُخطّى و`assembleDebug`
#    ينجح، فيُرفع أثرٌ من ٣١٫٧ م.ب هو حزمةُ **تصحيح** ترفضها قوقل.
#
# 🔴 والعقدُ **صُمِّم كي لا يمرّ فراغاً**، وهذه مواضعُه الأربعة:
#    ① «لم يُعثر على خطوات» ليس نجاحاً: صفرُ زوجٍ في `CONTRACT_STEPS` ⇒ فشل.
#      (لو تُرك فارغاً — بخطأ YAML مثلاً — لمرّ العقدُ أخضرَ وهو لا يقرأ شيئاً.)
#    ② وحالةٌ **فارغة** ليست «success»: معرّفٌ مكتوبٌ خطأً في السير يُعطي
#      سلسلةً فارغة، فيُتَّهم لا يُغتفَر. و`check-release-contract.js` يفحص
#      أن كلَّ معرّفٍ هنا معلَنٌ فعلاً في نفس المهمّة.
#    ③ ولا يُقاس «الاتّجاه» بل **المُخرَج**: يُشترط وجودُ ملفِّ الحزمة فعلاً
#      (`CONTRACT_ARTIFACT` + النمط) لا مجرّد نجاحِ الخطوات.
#    ④ ولا عتبةَ رقميّةً مخترعة: كلُّ شرطٍ هنا «هذه الحالةُ = success» أو
#      «هذا الملفُّ موجود» — لا حجمَ أدنى ولا عدداً مُفترضاً.
#
# 🪤 وحالةُ «بناءِ تحقّق» (بلا نيّة إصدار) تخرج بصفرٍ عمداً: عقدٌ مُفرِطٌ
#    يُفشل كلَّ بناءِ تحقّقٍ يُلغيه صاحبُه بعد أسبوع.
# 🪤 والصَدَفةُ bash صراحةً ويُقسَّم بـ`read -r -a`: قاعدةُ المشروع أن zsh
#    لا يُقسّم المتغيّرات، فحلقةٌ على سلسلةٍ تدور مرّةً واحدةً **بصمت**.
# ═══════════════════════════════════════════════════════════════════════════
set -uo pipefail

PLATFORM="${PLATFORM:-?}"
EVENT="${EVENT:-}"
SIGN_OK="${SIGN_OK:-}"
SIGN_MISSING="${SIGN_MISSING:-}"
CONTRACT_STEPS="${CONTRACT_STEPS:-}"
CONTRACT_ARTIFACT="${CONTRACT_ARTIFACT:-}"
CONTRACT_ARTIFACT_GLOB="${CONTRACT_ARTIFACT_GLOB:-}"

# نيّةُ الإصدار: دفعُ وسمٍ، أو طلبٌ يدويٌّ بـrelease=true.
INTENT=false
if [ "${INTENT_INPUT:-false}" = "true" ] || [ "$EVENT" = "push" ]; then INTENT=true; fi

echo "── عقدُ الإصدار ($PLATFORM) ──"
echo "نيّةُ إصدار=$INTENT · الحدث=$EVENT · الأسرار=${SIGN_OK:-فارغة}"
echo "حالاتُ الخطوات: ${CONTRACT_STEPS:-(لا شيء)}"

if [ "$INTENT" != "true" ]; then
  echo "ℹ️ بناءُ تحقّقٍ فقط — لا عقدَ رفع."
  echo "   (وهذه هي الحالةُ الوحيدة التي يجوز فيها أخضرُ بلا حزمةٍ موقَّعة.)"
  exit 0
fi

fail=0
say() { echo "::error title=عقدُ الإصدار::$1"; fail=1; }

# ① الأسرار
[ "$SIGN_OK" = "true" ] \
  || say "طُلب إصدارٌ والأسرارُ ناقصة: ${SIGN_MISSING:-غيرُ معروف}. لا توقيعَ ⇒ لا رفعَ ⇒ لا أخضر."

# ② الخطوات — واحدةً واحدة، وبأسمائها
read -r -a _pairs <<< "$CONTRACT_STEPS"
n=0
for pair in "${_pairs[@]:-}"; do
  [ -n "$pair" ] || continue
  name="${pair%%=*}"
  out="${pair#*=}"
  [ "$name" != "$pair" ] || { say "زوجٌ مشوّهٌ في عقد الإصدار: «$pair»"; continue; }
  n=$((n + 1))
  [ "$out" = "success" ] \
    || say "الخطوةُ «$name» حالتُها «${out:-فارغة}» لا «success» — طُلب إصدارٌ ولم تُنفَّذ."
done
# 🔴 صفرُ خطوةٍ ليس نجاحاً — هو عقدٌ لا يقرأ شيئاً.
[ "$n" -gt 0 ] \
  || say "عقدُ الإصدار لم يقرأ أيَّ خطوة (CONTRACT_STEPS فارغة) — حارسٌ لا يحرس."

# ③ المُخرَج نفسُه موجودٌ على القرص
if [ -n "$CONTRACT_ARTIFACT" ] && [ -n "$CONTRACT_ARTIFACT_GLOB" ]; then
  # 🪤 ويُعدّ الملفُّ بـ`find` لا بتوسيعِ صَدَفةٍ: نمطٌ لا يطابق شيئاً يبقى
  #    نصّاً حرفياً في bash فيبدو «موجوداً».
  cnt=$(find "$CONTRACT_ARTIFACT" -maxdepth 3 -name "$CONTRACT_ARTIFACT_GLOB" 2>/dev/null | wc -l | tr -d ' ')
  echo "حزمُ «$CONTRACT_ARTIFACT_GLOB» في $CONTRACT_ARTIFACT: ${cnt:-0}"
  [ "${cnt:-0}" -ge 1 ] \
    || say "طُلب إصدارٌ ولا ملفَّ «$CONTRACT_ARTIFACT_GLOB» على القرص — نجاحُ الخطوات لا يكفي، يُقاس المُخرَج."
else
  say "عقدُ الإصدار بلا عقدِ مُخرَج (CONTRACT_ARTIFACT) — يُضبط في السير."
fi

if [ "$fail" != "0" ]; then
  echo "❌ طُلب إصدارٌ ولم يصل المتجرَ شيء. لا يُعلن أخضر."
  exit 1
fi
echo "✅ عقدُ الإصدار ($PLATFORM): موقَّعٌ · مُصدَّر · مُثبَتُ التوقيع · مرفوعٌ · والحزمةُ على القرص"
